// Extract attention items from Pi service request
const body = $input.first().json.body || $input.first().json;
const items = body.attentionItems || body.items || [];
const phoneNumber = body.phoneNumber || body.to || '+13055551234'; // Default/configured number
const urgency = body.urgency || 'normal';

// Build summary for TTS
let summary;
if (items.length === 0) {
  summary = "Hey, just checking in. Everything looks good on my end.";
} else if (items.length === 1) {
  const item = items[0];
  if (item.type === 'error') {
    summary = `Hey, I ran into an issue with ${item.sessionName || 'a session'}. ${item.preview || item.content || 'Want me to explain?'}`;
  } else if (item.type === 'question') {
    summary = `Hey, I have a question about ${item.sessionName || 'something'}. ${item.preview || item.content || 'Got a minute?'}`;
  } else {
    summary = `Hey, something needs your attention on ${item.sessionName || 'a session'}. ${item.preview || ''}`;
  }
} else {
  const errorCount = items.filter(i => i.type === 'error').length;
  const questionCount = items.filter(i => i.type === 'question').length;
  let parts = [];
  if (errorCount > 0) parts.push(`${errorCount} error${errorCount > 1 ? 's' : ''}`);
  if (questionCount > 0) parts.push(`${questionCount} question${questionCount > 1 ? 's' : ''}`);
  if (parts.length === 0) parts.push(`${items.length} item${items.length > 1 ? 's' : ''}`);
  summary = `Hey, I've got ${parts.join(' and ')} that need your attention. Want to go through them?`;
}

// Build initial state
const state = {
  history: [],
  lastIntent: null,
  sessionContext: {},
  turnCount: 0,
  consecutiveTimeouts: 0,
  attentionItems: items,
  currentItemIndex: 0,
  callDirection: 'outbound'
};

return {
  json: {
    phoneNumber,
    urgency,
    attentionItems: items,
    itemCount: items.length,
    greetingSummary: summary,
    clientState: Buffer.from(JSON.stringify(state)).toString('base64'),
    state
  }
};

// Call was answered - extract state and prepare greeting
const webhookData = $('Telnyx Outbound Webhook').first().json;
const payload = webhookData.data.payload;

let state;
try {
  const decoded = Buffer.from(payload.client_state || '', 'base64').toString('utf-8');
  state = JSON.parse(decoded);
} catch (e) {
  state = {
    history: [],
    lastIntent: null,
    sessionContext: {},
    turnCount: 0,
    consecutiveTimeouts: 0,
    attentionItems: [],
    currentItemIndex: 0,
    callDirection: 'outbound'
  };
}

// Build greeting based on attention items
const items = state.attentionItems || [];
let greeting;

if (items.length === 0) {
  greeting = "Hey, just checking in. Everything looks good on my end. Need anything?";
} else if (items.length === 1) {
  const item = items[0];
  if (item.type === 'error') {
    greeting = `Hey, I ran into an issue with ${item.sessionName || 'a session'}. ${item.preview || item.content?.slice(0, 100) || 'Want me to explain what happened?'}`;
  } else if (item.type === 'question') {
    greeting = `Hey, I have a question about ${item.sessionName || 'something I\'m working on'}. ${item.preview || item.content?.slice(0, 100) || 'Got a minute?'}`;
  } else {
    greeting = `Hey, something needs your attention on ${item.sessionName || 'one of the sessions'}. ${item.preview || 'Want me to fill you in?'}`;
  }
} else {
  const errorCount = items.filter(i => i.type === 'error').length;
  const questionCount = items.filter(i => i.type === 'question').length;
  let parts = [];
  if (errorCount > 0) parts.push(`${errorCount} error${errorCount > 1 ? 's' : ''}`);
  if (questionCount > 0) parts.push(`${questionCount} question${questionCount > 1 ? 's' : ''}`);
  if (parts.length === 0) parts.push(`${items.length} thing${items.length > 1 ? 's' : ''}`);
  greeting = `Hey, I've got ${parts.join(' and ')} that need your attention. Want to go through them?`;
}

state.history.push({ role: 'assistant', content: greeting });

return {
  json: {
    greeting,
    callControlId: payload.call_control_id,
    clientState: Buffer.from(JSON.stringify(state)).toString('base64'),
    state,
    itemCount: items.length
  }
};

// Extract state and transcript from gather.ended event
const webhookData = $('Telnyx Outbound Webhook').first().json;
const payload = webhookData.data.payload;

let state;
try {
  const decoded = Buffer.from(payload.client_state || '', 'base64').toString('utf-8');
  state = JSON.parse(decoded);
} catch (e) {
  state = {
    history: [],
    lastIntent: null,
    sessionContext: {},
    turnCount: 0,
    consecutiveTimeouts: 0,
    attentionItems: [],
    currentItemIndex: 0,
    callDirection: 'outbound'
  };
}

const transcript = payload.speech?.transcript || '';
const speechConfidence = payload.speech?.confidence || 0;
const timedOut = !transcript || transcript.trim() === '';

if (!timedOut) {
  state.history.push({ role: 'user', content: transcript });
  state.consecutiveTimeouts = 0;
}

if (state.history.length > 10) {
  state.history = state.history.slice(-10);
}

state.turnCount++;

return {
  json: {
    callControlId: payload.call_control_id,
    transcript,
    speechConfidence,
    timedOut,
    state,
    turnCount: state.turnCount,
    attentionItems: state.attentionItems || [],
    currentItemIndex: state.currentItemIndex || 0
  }
};

// Handle timeout
const state = { ...$json.state };
const timeoutCount = (state.consecutiveTimeouts || 0) + 1;
state.consecutiveTimeouts = timeoutCount;

let responseText;
let shouldHangup = false;

if (timeoutCount >= 2) {
  responseText = "I'll let you go for now. I'll try again later if needed!";
  shouldHangup = true;
} else {
  responseText = "Still there? I didn't catch that.";
}

const audioTimestamp = Date.now();

return {
  json: {
    callControlId: $json.callControlId,
    responseText,
    shouldHangup,
    state,
    clientState: Buffer.from(JSON.stringify(state)).toString('base64'),
    audioTimestamp,
    intent: 'timeout'
  }
};

// Build Claude intent classification prompt for outbound call context
const { transcript, state, attentionItems, currentItemIndex } = $json;

const historyText = state.history
  .map(h => `${h.role === 'user' ? 'User' : 'Assistant'}: ${h.content}`)
  .join('\n');

// Build context about pending items
let itemsContext = '';
if (attentionItems && attentionItems.length > 0) {
  itemsContext = `\n\nPending attention items:\n${attentionItems.map((item, i) => 
    `${i + 1}. [${item.type}] ${item.sessionName}: ${item.preview || item.content?.slice(0, 100) || 'No preview'}`
  ).join('\n')}`;
}

const systemPrompt = `You are an intent classifier for an outbound voice assistant that called the user about attention items from Claude Code sessions.

Context: This is an OUTBOUND call - we called the user to notify them about issues/questions.${itemsContext}

Classify the user's speech into ONE of these intents:
- acknowledge: User acknowledges the information ("okay", "got it", "thanks")
- explain_more: User wants more details about an item ("tell me more", "what happened")
- resolve_item: User wants to mark an item as resolved ("that's fine", "ignore it", "skip")
- next_item: User wants to hear the next attention item
- send_response: User wants to send a message/instruction to a session
- check_status: User wants status of a specific session
- end_call: User wants to end the phone call ("bye", "goodbye", "that's all")
- unknown: Cannot determine intent

Extract these fields if present:
- sessionName: Which project/session name is referenced (null if not mentioned)
- message: The actual content/instruction to send (null if not applicable)
- itemIndex: Which item number they're referring to (null if not mentioned)

Respond with ONLY valid JSON:
{"intent": "...", "sessionName": "...", "message": "...", "itemIndex": null, "confidence": 0.0-1.0}`;

const userMessage = historyText
  ? `Conversation so far:\n${historyText}\n\nUser just said: "${transcript}"\n\nClassify the intent.`
  : `User said: "${transcript}"\n\nClassify the intent.`;

return {
  json: {
    systemPrompt,
    userMessage,
    callControlId: $json.callControlId,
    transcript,
    state,
    attentionItems,
    currentItemIndex
  }
};

// Parse Claude's intent classification response
const claudeResponse = $input.first().json;
const prevData = $('Build Intent Prompt').first().json;

let intentData;
try {
  const text = claudeResponse.content[0].text;
  let jsonStr = text;
  const jsonMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/) || text.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    jsonStr = jsonMatch[1] || jsonMatch[0];
  }
  intentData = JSON.parse(jsonStr.trim());
} catch (e) {
  intentData = { intent: 'unknown', sessionName: null, message: null, itemIndex: null, confidence: 0 };
}

return {
  json: {
    intent: intentData.intent || 'unknown',
    sessionName: intentData.sessionName || null,
    message: intentData.message || prevData.transcript,
    itemIndex: intentData.itemIndex,
    confidence: intentData.confidence || 0,
    callControlId: prevData.callControlId,
    transcript: prevData.transcript,
    state: prevData.state,
    attentionItems: prevData.attentionItems,
    currentItemIndex: prevData.currentItemIndex
  }
};

// Build response based on intent for outbound call context
const intentData = $('Parse Intent').first().json;
const intent = intentData.intent;
const state = { ...intentData.state };
const items = intentData.attentionItems || [];
let currentIndex = intentData.currentItemIndex || 0;

let responseText = '';

switch (intent) {
  case 'acknowledge': {
    // User acknowledged, ask if they want to go through more items or need anything else
    if (items.length > currentIndex + 1) {
      responseText = "Got it. Want to hear about the next item, or is there anything else?";
    } else if (items.length > 0) {
      responseText = "Alright, that's everything I had. Anything else you need?";
    } else {
      responseText = "Okay! Anything else I can help with?";
    }
    break;
  }
  case 'explain_more': {
    // Give more details about current attention item
    const item = items[currentIndex];
    if (item) {
      const fullContent = item.content || item.message || 'No additional details available.';
      responseText = `Here's more detail: ${fullContent.slice(0, 300)}${fullContent.length > 300 ? '... Want me to continue?' : ''}`;
    } else {
      responseText = "I don't have any more details on that. Is there something specific you'd like to know?";
    }
    break;
  }
  case 'resolve_item': {
    // Mark item as resolved
    const item = items[currentIndex];
    if (item) {
      item.resolved = true;
      responseText = `Okay, I've marked that as resolved. ${items.length > currentIndex + 1 ? 'Want to hear the next one?' : 'That was the last item. Anything else?'}`;
    } else {
      responseText = "Nothing to resolve right now. Need anything else?";
    }
    break;
  }
  case 'next_item': {
    // Move to next attention item
    currentIndex++;
    const item = items[currentIndex];
    if (item) {
      state.currentItemIndex = currentIndex;
      if (item.type === 'error') {
        responseText = `Next up: ${item.sessionName || 'A session'} has an error. ${item.preview || item.content?.slice(0, 100) || 'Want details?'}`;
      } else if (item.type === 'question') {
        responseText = `Next: Question from ${item.sessionName || 'a session'}. ${item.preview || item.content?.slice(0, 100) || ''}`;
      } else {
        responseText = `Next item from ${item.sessionName || 'a session'}: ${item.preview || item.content?.slice(0, 100) || 'Want to hear more?'}`;
      }
    } else {
      responseText = "That was the last item. Anything else you need?";
    }
    break;
  }
  case 'send_response': {
    // User wants to send a message - we'll need to call Pi API
    responseText = `Got it, I'll pass that along to ${intentData.sessionName || 'the session'}. Anything else?`;
    break;
  }
  case 'check_status': {
    responseText = "Let me check on that for you.";
    break;
  }
  case 'end_call': {
    responseText = "Alright, I'll let you go. Talk soon!";
    break;
  }
  default:
    responseText = "Sorry, I didn't catch that. Could you say it again?";
}

state.lastIntent = intent;
state.consecutiveTimeouts = 0;
state.history.push({ role: 'assistant', content: responseText });

return {
  json: {
    responseText,
    callControlId: intentData.callControlId,
    state,
    clientState: Buffer.from(JSON.stringify(state)).toString('base64'),
    intent,
    audioTimestamp: Date.now(),
    shouldHangup: intent === 'end_call'
  }
};

// Log outbound call on hangup
const webhookData = $('Telnyx Outbound Webhook').first().json;
const payload = webhookData.data?.payload || {};

return {
  json: {
    direction: 'outbound',
    telnyx_call_control_id: payload.call_control_id || null,
    telnyx_call_leg_id: payload.call_leg_id || null,
    status: 'completed',
    caller_number: payload.to || null,
    started_at: new Date().toISOString(),
    metadata: {
      hangup_cause: payload.hangup_cause || 'normal',
      call_direction: 'outbound'
    }
  }
};
